// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
        // the test contract deploys and initializes c, so it becomes the owner
        c.initialize();
    }

    function testFuzz_property(uint160 rawNewOwner) public {
        // WIDE domain: the full uint160 space, zero included (no assumption
        // excludes the bug-triggering input newOwner == address(0)).
        address newOwner = address(rawNewOwner);

        // only the current owner (the test contract) may call transferOwnership
        vm.prank(address(this));
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Universal rule: whenever a transferOwnership call by the owner
        // completes, the owner is set to the requested non-zero newOwner.
        // Reference: reverts for newOwner == 0, so the rule holds for all inputs.
        // Mutant: completes for newOwner == 0, leaving c.owner() == address(0).
        assertTrue(!ok || (c.owner() == newOwner && c.owner() != address(0)));
    }
}
